import openpyxl

path = '/opt/render/project/src/agent_workspace/OSP_Telecom_Leads_NetNew_EVALUATED.xlsx'
wb = openpyxl.load_workbook(path, data_only=True)
ws = wb['QUALIFIED LEADS']

# Locate the real header row: the row containing 'Prospect Priority' or 'Company'.
header_row = None
for idx, row in enumerate(ws.iter_rows(min_row=1, max_row=15, values_only=True), start=1):
    vals = [str(v).strip() for v in row if v is not None]
    if any(v in ('Prospect Priority', 'Company', 'Company Name', 'Website', 'URL') for v in vals):
        header_row = idx
        break

print('Detected header row:', header_row)
if header_row is None:
    for idx, row in enumerate(ws.iter_rows(min_row=1, max_row=5, values_only=True), start=1):
        print('ROW', idx, [str(v)[:60] if v is not None else None for v in row][:20])
else:
    headers = [str(c.value).strip() if c.value is not None else '' for c in ws[header_row]]
    print('Headers:', headers)
    pp_idx = headers.index('Prospect Priority') if 'Prospect Priority' in headers else None
    rows = []
    for r in ws.iter_rows(min_row=header_row + 1, values_only=True):
        if pp_idx is not None and r and r[pp_idx] == 'High Priority':
            rows.append(dict((h, r[i]) for i, h in enumerate(headers) if h and i < len(r) and r[i] not in (None, '')))
    print('High Priority rows:', len(rows))
    for d in rows:
        print(json.dumps(d, default=str)[:900])
        print('---')
